import { useState } from "react";
import { createFileRoute } from "@tanstack/react-router";
import { useQuery } from "@tanstack/react-query";
import { BadgeCheck, FileCheck2, Fingerprint, ShieldCheck } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { EmptyState, ErrorState, LoadingState } from "@/components/states/DataStates";
import { fmtDateTime, inr } from "@/lib/procurement";
import { cn } from "@/lib/utils";

export const Route = createFileRoute("/_authenticated/vendor/bid-passport")({ head: () => ({ meta: [{ title: "Bid Passport — GeMShield" }, { name: "description", content: "Immutable, replayable records of final decisions on your bids." }] }), component: VendorBidPassport });
type Passport = { id:string; bid_id:string; issued_at:string; passport_hash:string; passport_snapshot: Record<string, any>; decision:{decision:string;justification:string;decision_hash:string;decided_at:string}|null };

function VendorBidPassport() {
  const [selected,setSelected]=useState<Passport|null>(null);
  const q=useQuery({queryKey:["my-bid-passports"],queryFn:async()=>{const {data,error}=await supabase.from("bid_passports").select("*, decision:final_decisions(decision,justification,decision_hash,decided_at)").order("issued_at",{ascending:false});if(error)throw error;return data as unknown as Passport[];}});
  return <div className="space-y-3"><header className="flex items-center gap-3 rounded-xl border border-border bg-card p-4"><span className="flex h-12 w-12 items-center justify-center rounded-lg bg-success/10 text-success"><BadgeCheck className="h-6 w-6"/></span><div><h1 className="font-display text-2xl font-bold">Bid Passport</h1><p className="text-sm text-muted-foreground">Verified, immutable and replayable records issued after an officer’s final decision.</p></div></header>
    {q.isPending?<LoadingState label="Loading bid passports…"/>:q.error?<ErrorState error={q.error} onRetry={()=>q.refetch()}/>:!q.data.length?<EmptyState title="No Bid Passports issued" description="A passport appears only after a submitted bid completes verification, any required human review, and an officer’s final decision."/>:<div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{q.data.map((p)=>{const s=p.passport_snapshot||{},t=s["tender"]||{},b=s["bid"]||{},c=s["compliance"]||{};return <article key={p.id} className="rounded-xl border border-border bg-card p-4 shadow-[var(--shadow-card)]"><div className="flex items-start gap-2"><ShieldCheck className="h-6 w-6 text-success"/><div className="min-w-0"><p className="font-semibold">{t.reference_no??"Bid Passport"}</p><p className="truncate text-xs text-muted-foreground">{t.title??p.bid_id}</p></div><span className={cn("ml-auto rounded px-2 py-1 text-[10px] font-bold uppercase",p.decision?.decision==="compliant"?"bg-success/10 text-success":"bg-destructive/10 text-destructive")}>{p.decision?.decision?.replace(/_/g," ")}</span></div><dl className="mt-3 grid grid-cols-2 gap-2 text-xs"><div><dt className="text-muted-foreground">Issued</dt><dd>{fmtDateTime(p.issued_at)}</dd></div><div><dt className="text-muted-foreground">Bid value</dt><dd>{inr(b.quoted_amount??null)}</dd></div><div><dt className="text-muted-foreground">Score</dt><dd>{c.score??"—"}</dd></div><div><dt className="text-muted-foreground">Rules</dt><dd>{c.rules_version??"—"}</dd></div></dl><Button className="mt-3 w-full" size="sm" variant="outline" onClick={()=>setSelected(p)}><FileCheck2 className="mr-1 h-4 w-4"/>View Passport</Button></article>})}</div>}
    {selected&&<section className="rounded-xl border border-primary/30 bg-card p-4"><div className="flex items-center gap-2"><Fingerprint className="h-5 w-5 text-primary"/><h2 className="font-semibold">Passport integrity record</h2><Button className="ml-auto" variant="outline" size="sm" onClick={()=>setSelected(null)}>Close</Button></div><dl className="mt-3 grid gap-2 text-xs md:grid-cols-[150px_1fr]"><dt className="text-muted-foreground">Passport ID</dt><dd className="font-mono break-all">{selected.id}</dd><dt className="text-muted-foreground">Passport SHA-256</dt><dd className="font-mono break-all">{selected.passport_hash}</dd><dt className="text-muted-foreground">Decision SHA-256</dt><dd className="font-mono break-all">{selected.decision?.decision_hash}</dd><dt className="text-muted-foreground">Officer justification</dt><dd>{selected.decision?.justification}</dd></dl><h3 className="mt-4 text-sm font-semibold">Preserved decision snapshot</h3><pre className="mt-2 max-h-[420px] overflow-auto rounded-lg bg-muted p-3 text-[11px]">{JSON.stringify(selected.passport_snapshot,null,2)}</pre></section>}
  </div>;
}